import React, { useState } from "react";
import { View, Text, TextInput, TouchableOpacity, Modal, StyleSheet } from "react-native";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

export default function App() {
  const [peso, setPeso] = useState("");
  const [altura, setAltura] = useState("");
  const [imc, setImc] = useState(null);
  const [classificacao, setClassificacao] = useState("");
  const [dica, setDica] = useState("");
  const [modalVisible, setModalVisible] = useState(false);

  const calcularIMC = () => {
    const pesoNum = parseFloat(peso.replace(",", "."));
    const alturaNum = parseFloat(altura.replace(",", "."));

    // 🧠 Validações básicas
    if (!peso || !altura) {
      toast.warn("Preencha todos os campos!");
      return;
    }

    if (isNaN(pesoNum) || isNaN(alturaNum)) {
      toast.error("Digite apenas números válidos!");
      return;
    }

    // ⚠️ Validações realistas
    if (pesoNum < 20 || pesoNum > 350) {
      toast.error("Peso fora dos limites plausíveis (20kg a 350kg).");
      return;
    }

    if (alturaNum < 0.8 || alturaNum > 2.5) {
      toast.error("Altura fora dos limites plausíveis (0.8m a 2.5m).");
      return;
    }

    const valorIMC = pesoNum / (alturaNum * alturaNum);
    const imcFormatado = valorIMC.toFixed(2);

    const { classificacao, dica } = gerarClassificacaoEDica(valorIMC);

    setImc(imcFormatado);
    setClassificacao(classificacao);
    setDica(dica);
    setModalVisible(true);
  };

  const gerarClassificacaoEDica = (valor) => {
    if (valor < 18.5)
      return {
        classificacao: "Abaixo do peso",
        dica: "Mantenha uma alimentação balanceada e busque orientação médica ou nutricional para ganhar peso de forma saudável.",
      };
    if (valor < 24.9)
      return {
        classificacao: "Peso normal",
        dica: "Parabéns! Continue com hábitos saudáveis, incluindo boa alimentação e prática regular de atividade física.",
      };
    if (valor < 29.9)
      return {
        classificacao: "Sobrepeso",
        dica: "Procure ajustar sua dieta e incluir mais exercícios físicos na rotina. Um nutricionista pode ajudar na reeducação alimentar.",
      };
    if (valor < 34.9)
      return {
        classificacao: "Obesidade Grau I",
        dica: "É importante adotar hábitos saudáveis e consultar um profissional de saúde para acompanhamento e orientação personalizada.",
      };
    if (valor < 39.9)
      return {
        classificacao: "Obesidade Grau II",
        dica: "Procure acompanhamento médico e nutricional. Pequenas mudanças graduais no estilo de vida podem trazer grandes resultados.",
      };
    return {
      classificacao: "Obesidade Grau III (mórbida)",
      dica: "Cuide da sua saúde com urgência. O acompanhamento médico é essencial para definir um plano de tratamento adequado.",
    };
  };

  const fecharModal = () => {
    setModalVisible(false);
    setPeso("");
    setAltura("");
    setImc(null);
    setClassificacao("");
    setDica("");
  };

  return (
    <View style={styles.container}>
      <Text style={styles.titulo}>Calculadora de IMC</Text>

      <TextInput
        style={styles.input}
        placeholder="Peso (kg)"
        keyboardType="numeric"
        value={peso}
        onChangeText={setPeso}
      />
      <TextInput
        style={styles.input}
        placeholder="Altura (m)"
        keyboardType="numeric"
        value={altura}
        onChangeText={setAltura}
      />

      <TouchableOpacity style={styles.botao} onPress={calcularIMC}>
        <Text style={styles.textoBotao}>Calcular</Text>
      </TouchableOpacity>

      {/* Modal de resultado */}
      <Modal visible={modalVisible} transparent animationType="fade">
        <View style={styles.modalContainer}>
          <View style={styles.modalContent}>
            <Text style={styles.resultado}>Seu IMC é {imc}</Text>
            <Text style={styles.classificacao}>{classificacao}</Text>
            <Text style={styles.dica}>{dica}</Text>

            <TouchableOpacity style={styles.botaoFechar} onPress={fecharModal}>
              <Text style={styles.textoFechar}>Fechar</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {/* Toastify */}
      <ToastContainer position="top-center" autoClose={2500} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "#f2f2f2",
    padding: 20,
  },
  titulo: {
    fontSize: 28,
    fontWeight: "bold",
    marginBottom: 25,
  },
  input: {
    width: "80%",
    borderWidth: 1,
    borderColor: "#ccc",
    borderRadius: 8,
    padding: 12,
    marginBottom: 15,
    backgroundColor: "#fff",
  },
  botao: {
    backgroundColor: "#007BFF",
    paddingVertical: 12,
    paddingHorizontal: 25,
    borderRadius: 8,
  },
  textoBotao: {
    color: "#fff",
    fontWeight: "bold",
    fontSize: 16,
  },
  modalContainer: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "rgba(0,0,0,0.5)",
  },
  modalContent: {
    backgroundColor: "#fff",
    borderRadius: 12,
    padding: 25,
    alignItems: "center",
    width: "80%",
  },
  resultado: {
    fontSize: 22,
    fontWeight: "bold",
    marginBottom: 10,
  },
  classificacao: {
    fontSize: 18,
    fontWeight: "bold",
    color: "#444",
    marginBottom: 10,
  },
  dica: {
    fontSize: 16,
    textAlign: "center",
    color: "#666",
    marginBottom: 20,
  },
  botaoFechar: {
    backgroundColor: "#FF4444",
    paddingVertical: 10,
    paddingHorizontal: 20,
    borderRadius: 8,
  },
  textoFechar: {
    color: "#fff",
    fontWeight: "bold",
  },
});
